215	func (s *GitStore) ReadSession(ctx context.Context, ref SessionRef, opts ...ReadOption) (*SessionContent, error) {
216		if err := ref.validate(); err != nil {
217			return nil, err
218		}
219	
220		readOpts := applyReadOptions(opts)
221		sessionIndex, err := s.resolveSessionIndex(ctx, ref)
222		if err != nil {
223			return nil, err
224		}
225	
226		switch readOpts.mode {
227		case sessionReadFull:
228			return s.ReadSessionContent(ctx, ref.checkpointID, sessionIndex)
229		case sessionReadMetadataOnly:
230			metadata, readErr := s.ReadSessionMetadata(ctx, ref.checkpointID, sessionIndex)
231			if readErr != nil {
232				return nil, readErr
233			}
234			if metadata == nil {
235				return nil, ErrCheckpointNotFound
236			}
237			return &SessionContent{Metadata: *metadata}, nil
238		case sessionReadMetadataAndPrompts:
239			return s.ReadSessionMetadataAndPrompts(ctx, ref.checkpointID, sessionIndex)
240		default:
241			return nil, errors.New("unknown session read mode")
242		}
