245	func (s *GitStore) WriteSession(ctx context.Context, ref SessionRef, session Session) error {
246		if err := ref.validateForWrite(); err != nil {
247			return err
248		}
249	
250		opts := session
251		switch {
252		case opts.CheckpointID.IsEmpty():
253			opts.CheckpointID = ref.checkpointID
254		case opts.CheckpointID != ref.checkpointID:
255			return fmt.Errorf("session checkpoint ID %s does not match ref %s", opts.CheckpointID, ref.checkpointID)
256		}
257		switch {
258		case opts.SessionID == "":
259			opts.SessionID = ref.sessionID
260		case opts.SessionID != ref.sessionID:
261			return fmt.Errorf("session ID %q does not match ref %q", opts.SessionID, ref.sessionID)
262		}
263		return s.WriteCommitted(ctx, opts)
264	}
