266	func (s *GitStore) UpdateSession(ctx context.Context, ref SessionRef, opts ...WriteOption) error {
267		if err := ref.validate(); err != nil {
268			return err
269		}
270	
271		writeOpts := applyWriteOptions(opts)
272		if !writeOpts.hasSessionUpdate() {
273			return errors.New("no session update options")
274		}
275	
276		if writeOpts.hasTranscriptUpdate() {
277			sessionID, err := s.resolveSessionID(ctx, ref)
278			if err != nil {
279				return err
280			}
281			if err := s.UpdateCommitted(ctx, UpdateCommittedOptions{
282				CheckpointID:     ref.checkpointID,
283				SessionID:        sessionID,
284				Transcript:       writeOpts.transcript,
285				Prompts:          writeOpts.prompts,
286				Agent:            writeOpts.agent,
287				SkillEvents:      writeOpts.skillEvents,
288				PrecomputedBlobs: writeOpts.precomputedBlobs,
289			}); err != nil {
290				return err
291			}
292		}
293	
294		if writeOpts.summarySet {
295			return s.updateSessionSummary(ctx, ref, writeOpts.summary)
296		}
297		return nil
298	}
299	
300	func (s *GitStore) UpdateCheckpoint(ctx context.Context, checkpointID id.CheckpointID, opts ...WriteOption) error {
301		writeOpts := applyWriteOptions(opts)
302		if !writeOpts.attributionSet {
303			return errors.New("no checkpoint update options")
304		}
305		return s.UpdateCheckpointSummary(ctx, checkpointID, writeOpts.attribution)
306	}
307	
308	func applyReadOptions(opts []ReadOption) readOptions {
309		readOpts := readOptions{mode: sessionReadFull}
310		for _, opt := range opts {
311			opt(&readOpts)
312		}
313		return readOpts
314	}
315	
316	func applyWriteOptions(opts []WriteOption) writeOptions {
317		var writeOpts writeOptions
318		for _, opt := range opts {
319			opt(&writeOpts)
320		}
321		return writeOpts
322	}
323	
324	func (opts writeOptions) hasTranscriptUpdate() bool {
325		return opts.transcriptSet || opts.promptsSet || opts.skillEventsSet || opts.precomputedBlobs != nil
326	}
327	
328	func (opts writeOptions) hasSessionUpdate() bool {
329		return opts.hasTranscriptUpdate() || opts.summarySet
330	}
331	
332	func (r SessionRef) validate() error {
333		if r.checkpointID.IsEmpty() {
334			return errors.New("session ref checkpoint ID is required")
335		}
336		if r.sessionRefMode == sessionRefID && r.sessionID == "" {
337			return errors.New("session ref session ID is required")
338		}
339		if r.sessionRefMode == sessionRefIndex && r.sessionIndex < 0 {
340			return fmt.Errorf("session ref index must be non-negative: %d", r.sessionIndex)
341		}
342		return nil
343	}
344	
345	func (r SessionRef) validateForWrite() error {
346		if err := r.validate(); err != nil {
347			return err
348		}
349		if r.sessionRefMode != sessionRefID {
350			return errors.New("write session requires a session ID ref")
351		}
352		return nil
353	}
354	
355	func (s *GitStore) resolveSessionID(ctx context.Context, ref SessionRef) (string, error) {
356		if ref.sessionID != "" {
357			return ref.sessionID, nil
358		}
359		content, err := s.ReadSession(ctx, ref, WithSessionMetadataOnly())
360		if err != nil {
361			return "", err
362		}
363		return content.Metadata.SessionID, nil
364	}
365	
366	func (s *GitStore) resolveSessionIndex(ctx context.Context, ref SessionRef) (int, error) {
367		if ref.sessionRefMode == sessionRefIndex {
368			return ref.sessionIndex, nil
369		}
370	
371		summary, err := s.ReadCheckpoint(ctx, ref.checkpointID)
372		if err != nil {
373			return 0, err
374		}
375		return s.resolveSessionIndexFromSummary(ctx, ref, summary)
376	}
377	
378	func (s *GitStore) resolveSessionIndexFromSummary(ctx context.Context, ref SessionRef, summary *CheckpointSummary) (int, error) {
379		if summary == nil || len(summary.Sessions) == 0 {
380			return 0, ErrCheckpointNotFound
381		}
382	
383		switch ref.sessionRefMode {
384		case sessionRefLatest:
385			return len(summary.Sessions) - 1, nil
386		case sessionRefIndex:
387			if ref.sessionIndex >= len(summary.Sessions) {
388				return 0, fmt.Errorf("session index %d out of range for checkpoint %s: %w", ref.sessionIndex, ref.checkpointID, ErrCheckpointNotFound)
389			}
390			return ref.sessionIndex, nil
391		case sessionRefID:
392			for index := range summary.Sessions {
393				metadata, err := s.ReadSessionMetadata(ctx, ref.checkpointID, index)
394				if err != nil {
395					return 0, err
396				}
397				if metadata != nil && metadata.SessionID == ref.sessionID {
398					return index, nil
399				}
400			}
401			return 0, fmt.Errorf("session %q not found in checkpoint %s: %w", ref.sessionID, ref.checkpointID, ErrCheckpointNotFound)
402		default:
403			return 0, errors.New("unknown session ref mode")
404		}
405	}
406	
407	func (s *GitStore) updateSessionSummary(ctx context.Context, ref SessionRef, summary *Summary) error {
408		if err := ctx.Err(); err != nil {
409			return err //nolint:wrapcheck // Propagating context cancellation
410		}
411		if err := s.ensureSessionsBranch(ctx); err != nil {
412			return fmt.Errorf("failed to ensure sessions branch: %w", err)
413		}
414	
415		parentHash, rootTreeHash, err := s.getSessionsBranchRef()
416		if err != nil {
417			return err
418		}
419	
420		basePath := ref.checkpointID.Path() + "/"
421		entries, err := s.flattenCheckpointEntries(rootTreeHash, ref.checkpointID.Path())
422		if err != nil {
423			return err
424		}
425	
426		rootMetadataPath := basePath + paths.MetadataFileName
427		rootEntry, exists := entries[rootMetadataPath]
428		if !exists {
429			return ErrCheckpointNotFound
430		}
431		checkpointSummary, err := s.readSummaryFromBlob(rootEntry.Hash)
432		if err != nil {
433			return fmt.Errorf("failed to read checkpoint summary: %w", err)
434		}
435		sessionIndex, err := s.resolveSessionIndexFromSummary(ctx, ref, checkpointSummary)
436		if err != nil {
437			return err
438		}
439	
440		sessionMetadataPath := fmt.Sprintf("%s%d/%s", basePath, sessionIndex, paths.MetadataFileName)
441		sessionEntry, exists := entries[sessionMetadataPath]
442		if !exists {
443			return fmt.Errorf("session metadata not found at %s", sessionMetadataPath)
444		}
445		existingMetadata, err := s.readMetadataFromBlob(sessionEntry.Hash)
446		if err != nil {
447			return fmt.Errorf("failed to read session metadata: %w", err)
448		}
449	
450		existingMetadata.Summary = redactSummary(summary)
451		metadataHash, err := createCommittedMetadataBlob(s, existingMetadata)
452		if err != nil {
453			return err
454		}
455		entries[sessionMetadataPath] = object.TreeEntry{
456			Name: sessionMetadataPath,
457			Mode: filemode.Regular,
458			Hash: metadataHash,
459		}
460	
461		newTreeHash, err := s.spliceCheckpointSubtree(ctx, rootTreeHash, ref.checkpointID, basePath, entries)
462		if err != nil {
463			return err
464		}
465		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
466		commitMsg := fmt.Sprintf("Update summary for checkpoint %s (session: %s)", ref.checkpointID, existingMetadata.SessionID)
467		newCommitHash, err := s.createCommit(ctx, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
468		if err != nil {
469			return err
470		}
471		return s.setPrimaryRef(newCommitHash)
472	}
473	
474	func createCommittedMetadataBlob(store *GitStore, metadata *CommittedMetadata) (plumbing.Hash, error) {
475		metadataJSON, err := jsonutil.MarshalIndentWithNewline(metadata, "", "  ")
476		if err != nil {
477			return plumbing.ZeroHash, fmt.Errorf("failed to marshal metadata: %w", err)
478		}
479		metadataHash, err := CreateBlobFromContent(store.repo, metadataJSON)
480		if err != nil {
481			return plumbing.ZeroHash, fmt.Errorf("failed to create metadata blob: %w", err)
482		}
483		return metadataHash, nil
484	}
